CREATE TABLE activity_events (id UUID PRIMARY KEY,workspace_id UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,project_id UUID REFERENCES projects(id) ON DELETE CASCADE,task_id UUID REFERENCES tasks(id) ON DELETE CASCADE,user_id UUID NOT NULL REFERENCES users(id),event_type TEXT NOT NULL,metadata JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX activity_workspace_created_idx ON activity_events(workspace_id,created_at DESC);
CREATE TABLE notifications (id UUID PRIMARY KEY,user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,workspace_id UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,type TEXT NOT NULL,title TEXT NOT NULL,message TEXT NOT NULL,entity_type TEXT,entity_id UUID,is_read BOOLEAN NOT NULL DEFAULT false,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
